"""Tests for the bulk discount module."""

from __future__ import annotations

from decimal import Decimal

import pytest

from pricing import LineItem
from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


# =============================================================================
# qualifies_for_bulk_discount tests
# =============================================================================


@pytest.mark.l4("C-4284227d")
def test_qualifies_for_bulk_discount_quantity_9_returns_false():
    item = LineItem("apple", Decimal("10.00"), 9)
    assert qualifies_for_bulk_discount(item) is False


@pytest.mark.l4("C-8764baca")
def test_qualifies_for_bulk_discount_quantity_10_returns_true():
    item = LineItem("apple", Decimal("10.00"), 10)
    assert qualifies_for_bulk_discount(item) is True


@pytest.mark.l4("C-e4015f6b")
def test_qualifies_for_bulk_discount_quantity_11_returns_true():
    item = LineItem("apple", Decimal("10.00"), 11)
    assert qualifies_for_bulk_discount(item) is True


# =============================================================================
# calculate_bulk_discount tests
# =============================================================================


@pytest.mark.l4("C-1caf4da3")
def test_calculate_bulk_discount_rounds_half_up():
    # 0.125 should round to 0.13 using half-up rounding
    item = LineItem("apple", Decimal("1.25"), 10)  # total = 12.50, 5% = 0.625 -> 0.63
    discount = calculate_bulk_discount(item)
    assert discount == Decimal("0.63")


@pytest.mark.l4("C-1caf4da3")
def test_calculate_bulk_discount_no_discount_for_quantity_9():
    item = LineItem("apple", Decimal("10.00"), 9)
    discount = calculate_bulk_discount(item)
    assert discount == Decimal("0.00")


@pytest.mark.l4("C-8764baca", "C-e4015f6b")
def test_calculate_bulk_discount_correct_5_percent_for_quantity_10():
    item = LineItem("apple", Decimal("10.00"), 10)  # total = 100.00, 5% = 5.00
    discount = calculate_bulk_discount(item)
    assert discount == Decimal("5.00")


@pytest.mark.l4("C-8764baca", "C-e4015f6b")
def test_calculate_bulk_discount_correct_5_percent_for_quantity_greater_than_10():
    item = LineItem("apple", Decimal("10.00"), 20)  # total = 200.00, 5% = 10.00
    discount = calculate_bulk_discount(item)
    assert discount == Decimal("10.00")


@pytest.mark.l4("C-1caf4da3", "C-8764baca", "C-e4015f6b")
def test_calculate_bulk_discount_non_negative():
    """Discount is always non-negative."""
    item = LineItem("apple", Decimal("10.00"), 10)
    discount = calculate_bulk_discount(item)
    assert discount >= Decimal("0.00")


@pytest.mark.l4("C-1caf4da3", "C-8764baca", "C-e4015f6b")
def test_calculate_bulk_discount_at_most_5_percent_of_line_total():
    """Discount is at most 5% of the line total."""
    item = LineItem("apple", Decimal("10.00"), 10)
    line_total = item.total
    discount = calculate_bulk_discount(item)
    assert discount <= line_total * Decimal("0.05")

